mapper.sql:
WITH events AS ( SELECT o.id, o.tenant_id, o.store_id, 'ORDER'::text AS kind, o.order_no AS biz_no, NULL::text AS related_no, o.member_id, o.paid_time AS event_time, COALESCE(o.received_amount, 0) AS amount, 0::numeric AS gift_amount, COALESCE(( SELECT SUM(p.amount) FROM salon_order_payment p WHERE p.order_id = o.id AND p.tenant_id = o.tenant_id AND p.deleted = 0 AND p.pay_method IN (1, 2, 3, 4, 8) ), 0) AS external_amount, COALESCE(o.point_deduct_amount, 0) AS point_amount, o.create_by AS operator_id FROM salon_order o WHERE o.deleted = 0 AND o.status IN (1, 2, 3) AND o.paid_time >= #{q.startTime} AND o.paid_time < #{q.endTime}
UNION ALL SELECT r.id, r.tenant_id, r.store_id, 'RECHARGE', r.recharge_no, NULL, r.member_id, r.pay_time, COALESCE(r.principal_amount, 0), COALESCE(r.gift_amount, 0), COALESCE(r.principal_amount, 0), 0, r.operator_id FROM salon_recharge_order r WHERE r.deleted = 0 AND r.status = 1 AND r.pay_time >= #{q.startTime} AND r.pay_time < #{q.endTime}
UNION ALL SELECT f.id, f.tenant_id, f.store_id, 'REFUND', f.refund_no, f.order_no, f.member_id, f.success_time, COALESCE(f.refund_amount, 0), 0, COALESCE(( SELECT SUM(p.amount) FROM salon_refund_payment p WHERE p.refund_id = f.id AND p.tenant_id = f.tenant_id AND p.deleted = 0 AND p.pay_method IN (1, 2, 3, 4, 8) ), 0), COALESCE(f.point_refund_amount, 0), f.create_by FROM salon_refund_order f WHERE f.deleted = 0 AND f.status = 1 AND f.success_time >= #{q.startTime} AND f.success_time < #{q.endTime}
)

FROM salon_store s WHERE s.deleted = 0
AND s.tenant_id = #{tenantId}
AND EXISTS ( SELECT 1 FROM salon_store_user u WHERE u.store_id = s.id AND u.tenant_id = s.tenant_id AND u.user_id = #{userId} AND u.deleted = 0 )

mapper.select:
SELECT COUNT(*) FILTER (WHERE kind = 'ORDER') AS order_count, COUNT(*) FILTER (WHERE kind = 'RECHARGE') AS recharge_count, COUNT(*) FILTER (WHERE kind = 'REFUND') AS refund_count, COUNT(DISTINCT member_id) FILTER (WHERE kind = 'ORDER') AS member_count, COALESCE(SUM(amount) FILTER (WHERE kind = 'ORDER'), 0) AS consumption_amount, COALESCE(SUM(amount) FILTER (WHERE kind = 'REFUND'), 0) AS refund_amount, COALESCE(SUM(CASE WHEN kind = 'ORDER' THEN amount WHEN kind = 'REFUND' THEN -amount ELSE 0 END), 0) AS net_consumption, COALESCE(SUM(amount) FILTER (WHERE kind = 'RECHARGE'), 0) AS recharge_amount, COALESCE(SUM(gift_amount), 0) AS recharge_gift, COALESCE(SUM(external_amount) FILTER (WHERE kind != 'REFUND'), 0) AS external_inflow, COALESCE(SUM(external_amount) FILTER (WHERE kind = 'REFUND'), 0) AS external_refund, COALESCE(SUM(CASE WHEN kind = 'REFUND' THEN -external_amount ELSE external_amount END), 0) AS net_cashflow, COALESCE(SUM(point_amount) FILTER (WHERE kind = 'ORDER'), 0) AS point_amount, ( SELECT COUNT(*) FROM salon_member WHERE deleted = 0 AND create_time >= #{q.startTime} AND create_time < #{q.endTime}
) AS new_member_count, ( SELECT COALESCE(SUM(change_amount), 0) FROM salon_member_balance_log WHERE deleted = 0 AND balance_type = 1 AND create_time < #{q.startTime}
) AS principal_opening, ( SELECT COALESCE(SUM(change_amount), 0) FROM salon_member_balance_log WHERE deleted = 0 AND balance_type = 1 AND create_time >= #{q.startTime} AND create_time < #{q.endTime}
) AS principal_change, ( SELECT COALESCE(SUM(change_amount), 0) FROM salon_member_balance_log WHERE deleted = 0 AND balance_type = 1 AND create_time < #{q.endTime}
) AS principal_closing, md5(COALESCE(string_agg( concat_ws(':', kind, id, event_time, amount, gift_amount, external_amount, point_amount), ',' ORDER BY kind, id ), '')) AS fingerprint FROM events

SELECT s.id AS entity_id, s.tenant_id, s.name AS label, COUNT(e.id) FILTER (WHERE e.kind = 'ORDER') AS count, COALESCE(SUM(e.amount) FILTER (WHERE e.kind = 'ORDER'), 0) AS amount, COALESCE(SUM(e.amount) FILTER (WHERE e.kind = 'REFUND'), 0) AS refund_amount, COALESCE(SUM(e.amount) FILTER (WHERE e.kind = 'RECHARGE'), 0) AS recharge_amount FROM salon_store s LEFT JOIN events e ON e.store_id = s.id AND e.tenant_id = s.tenant_id WHERE s.deleted = 0 AND s.id IN
#{storeId}
GROUP BY s.id, s.tenant_id, s.name ORDER BY amount DESC, s.id

mapper.sql:
SELECT e.id, e.tenant_id, e.store_id, e.kind, e.biz_no, e.related_no, e.member_id, e.event_time, e.amount, e.gift_amount, e.external_amount, e.point_amount, e.operator_id, s.name AS store_name, m.name AS member_name FROM events e LEFT JOIN salon_store s ON s.id = e.store_id AND s.tenant_id = e.tenant_id LEFT JOIN salon_member m ON m.id = e.member_id AND m.tenant_id = e.tenant_id AND m.deleted = 0
WHERE e.kind = #{q.kind}
ORDER BY e.event_time DESC, e.kind, e.id DESC

mapper.select:
SELECT d.id, d.tenant_id, d.store_id, s.name AS store_name, d.business_date, d.create_by, u.nickname AS operator_name, d.create_time, d.remark FROM salon_daily_settlement d LEFT JOIN salon_store s ON s.id = d.store_id AND s.tenant_id = d.tenant_id LEFT JOIN sys_user u ON u.id = d.create_by AND u.tenant_id = d.tenant_id AND u.deleted = 0 WHERE d.deleted = 0 AND d.business_date >= #{q.startDate} AND d.business_date <= #{q.endDate} AND d.store_id IN
#{storeId}
ORDER BY d.business_date DESC, d.id DESC
